<?php
declare(strict_types=1);
session_start();
$root=dirname(__DIR__,3);
$cfg=require $root.'/config.php';
date_default_timezone_set($cfg['timezone']??'America/Argentina/Buenos_Aires');
$db=new PDO('mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4',$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
if(empty($_SESSION['user'])){header('Location:index.php');exit;}
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function usd($n):string{return 'US$ '.number_format((float)$n,2,',','.');}
function imgData(?string $data,?string $mime):string{return ($data&&$mime)?'data:'.$mime.';base64,'.base64_encode($data):'';}
$id=(int)($_GET['id']??0);
$s=$db->prepare("SELECT q.*,p.project_number,p.name project_name,c.business_name,c.contact_name,c.cuit,c.email,c.whatsapp,c.address,c.city,c.province,pp.business_name partner_name,pl.name price_list_name FROM quotes q JOIN projects p ON p.id=q.project_id JOIN clients c ON c.id=p.client_id LEFT JOIN project_partners pp ON pp.id=p.partner_id LEFT JOIN price_lists pl ON pl.id=q.price_list_id WHERE q.id=?");
$s->execute([$id]);$q=$s->fetch();if(!$q)exit('Presupuesto inexistente.');
$s=$db->prepare("SELECT qi.*,p.image_data,p.image_mime FROM quote_items qi LEFT JOIN products p ON p.id=qi.product_id WHERE qi.quote_id=? ORDER BY qi.sort_order,qi.id");
$s->execute([$id]);$items=$s->fetchAll();
$logo='data:image/jpeg;base64,';
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Presupuesto <?=e($q['project_number'])?></title><style>
