ment .imgcol{width:15mm;text-align:center}.equipment .skucol{width:24mm}.equipment .qtycol{width:14mm;text-align:center}.equipment .pricecol{width:27mm;text-align:right}.equipment .totalcol{width:28mm;text-align:right}.prod-img{width:11mm;height:11mm;object-fit:contain;display:block;margin:auto}.img-empty{width:11mm;height:11mm;margin:auto;border:1px solid #e5e5e5;border-radius:4px;background:#fff}.sku{font-size:10px;font-weight:700}.desc{font-size:11px}.section-title{margin:13mm 0 5px;color:#ff6702;font-size:13px;font-weight:800}.labor{padding:9px 11px;background:#f6f6f6;border-left:4px solid #ff6702}.totals{width:74mm;margin:10mm 0 0 auto}.totals .line{display:flex;justify-content:space-between;padding:4px 0}.totals .grand{margin-top:5px;padding-top:7px;border-top:1.5px solid #222;color:#ff6702;font-size:17px;font-weight:800}.notes{margin-top:12mm;max-width:112mm}.notes h3{margin:0 0 5px;color:#ff6702;font-size:12px}.notes p{margin:0;color:#555;white-space:pre-wrap}.footer{position:absolute;left:16mm;right:16mm;bottom:12mm;z-index:2;display:flex;justify-content:space-between;align-items:flex-end;font-size:9px;color:#6b6f73}.footer strong{color:#ff6702;font-size:11px}.nowrap{white-space:nowrap}@media print{body{background:white}.actions{display:none}.sheet{margin:0;box-shadow:none;page-break-after:always}}
</style></head><body><div class="actions"><a class="dark" href="?a=quote_view&id=<?=$id?>">← Volver</a><button onclick="window.print()">Guardar / imprimir PDF</button></div><section class="sheet"><div class="bottom-dark"></div><div class="bottom-orange"></div><div class="head"><img class="logo" src="<?=$logo?>" alt="Punto Domótica"><div class="title"><h1>PRESUPUESTO</h1><div class="code"><?=e($q['project_number'])?> · v<?=e($q['version_no'])?></div></div></div><div class="meta"><div><h3>Presupuesto para:</h3><p><b><?=e($q['business_name'])?></b></p><?php if($q['contact_name']):?><p><?=e($q['contact_name'])?></p><?php endif;?><?php if($q['cuit']):?><p>CUIT <?=e($q['cuit'])?></p><?php endif;?><?php if($q['address']||$q['city']):?><p><?=e(trim(($q['address']??'').' · '.($q['city']??'').' '.($q['province']??''),' ·'))?></p><?php endif;?></div><div class="quote-meta"><div class="row"><b>Proyecto</b><span><?=e($q['project_number'])?></span></div><div class="row"><b>Obra</b><span><?=e($q['project_name'])?></span></div><div class="row"><b>Fecha</b><span><?=e(date('d/m/Y',strtotime($q['quote_date'])))?></span></div><?php if($q['partner_name']):?><div class="row"><b>Arquitecto</b><span><?=e($q['partner_name'])?></span></div><?php endif;?></div></div><table class="equipment"><thead><tr><th class="imgcol"></th><th class="skucol">SKU</th><th>Descripción</th><th class="qtycol">Cant.</th><th class="pricecol">Precio</th><th class="totalcol">Total</th></tr></thead><tbody><?php foreach($items as $it):$src=imgData($it['image_data']??null,$it['image_mime']??null);?><tr><td class="imgcol"><?php if($src):?><img class="prod-img" src="<?=e($src)?>" alt=""><?php else:?><div class="img-empty"></div><?php endif;?></td><td class="skucol"><span class="sku"><?=e($it['sku']?:'—')?></span></td><td><div class="desc"><?=e($it['description'])?></div></td><td class="qtycol"><?=e(rtrim(rtrim(number_format((float)$it['quantity'],2,'.',''),'0'),'.'))?></td><td class="pricecol nowrap"><?=usd($it['unit_price'])?></td><td class="totalcol nowrap"><b><?=usd($it['subtotal'])?></b></td></tr><?php endforeach;?></tbody></table><?php if((float)$q['labor_amount']>0):?><div class="section-title">Mano de obra</div><div class="labor"><?=e($q['labor_description']?:'Configuración, montaje y diseño de escenas')?></div><?php endif;?><div class="totals"><div class="line"><span>Equipamiento</span><b><?=usd($q['materials_amount'])?></b></div><?php if((float)$q['labor_amount']>0):?><div class="line"><span>Mano de obra</span><b><?=usd($q['labor_amount'])?></b></div><?php endif;?><div class="line grand"><span>TOTAL</span><span><?=usd($q['total'])?></span></div></div><?php if(trim((string)$q['notes'])!==''):?><div class="notes"><h3>Observaciones</h3><p><?=e($q['notes'])?></p></div><?php endif;?><div class="footer"><div><strong>Punto Domótica</strong><br>Soluciones de automatización y tecnología</div><div style="text-align:right">Valores expresados en dólares estadounidenses (USD)<br>Presupuesto <?=e($q['project_number'])?> · versión <?=e($q['version_no'])?></div></div></section></body></html>